import{BrowserProxy}from"./browser_proxy.js";let browserProxy=null;initializeExternalScript().then((()=>{if(!browserProxy){browserProxy=new BrowserProxy(requestSurvey)}}));function initializeExternalScript(){const script=document.createElement("script");script.type="text/javascript";script.src="https://www.gstatic.com/feedback/js/help/prod/service/lazy.min.js";const loaded=new Promise((r=>script.onload=r));document.head.appendChild(script);return loaded}async function requestSurvey(apiKey,triggerId,enableTesting,languageList,productSpecificDataJson){window.innerWidth=800;window.innerHeight=600;const helpApi=window.help.service.Lazy.create(0,{apiKey:apiKey,locale:"en-US"});let loadedSent=false;const surveyListener={surveyClosed:function(){browserProxy.handler.onSurveyClosed()},surveyPositioning:function(_,size,animationSpec){if(!loadedSent){setTimeout((function(){browserProxy.handler.onSurveyLoaded()}),animationSpec.duration*1e3);loadedSent=true}const wrapper=document.querySelector("#surveyWrapper");wrapper.style.width=`${size.width}px`;wrapper.style.height=`${size.height}px`;return{anchor:3,verticalMargin:.1,horizontalMargin:.1}}};helpApi.requestSurvey({triggerId:triggerId,enableTestingMode:enableTesting,preferredSurveyLanguageList:languageList,callback:requestSurveyCallbackParam=>{if(!requestSurveyCallbackParam.surveyData){browserProxy.handler.onSurveyClosed();return}helpApi.presentSurvey({surveyData:requestSurveyCallbackParam.surveyData,colorScheme:window.matchMedia("(prefers-color-scheme: dark)").matches?2:1,customZIndex:1e4,customLogoUrl:"https://www.gstatic.com/images"+"/branding/product/2x/chrome_48dp.png",listener:surveyListener,productData:{customData:productSpecificDataJson}})}})}